ch={e['id'] for e in LOG['edit']}
for i,x in orig.items():
    if i not in ch: assert x==I[i],i
print('items',len(IT),'visible',sum(1 for x in IT if not x.get('dup')),'edit',len(ch),'new',len(LOG['new']),'conf',len(LOG['conf']))
json.dump(d,open(SRC,'w'),ensure_ascii=False,indent=1)
json.dump(LOG,open('/workspace/edu/v27/log.json','w'),ensure_ascii=False,indent=1)
